#!/usr/bin/env python3
# gen_crc32c.py: writes crc32c_riscv64.s beside itself (run it from anywhere): CRC32c, slicing by 8, for the C906: one 64-bit
# load for 8 bytes, th.extu to cut a byte out, th.lrwu to load the table word by index (XTheadBb, XTheadMemIdx; Go's
# assembler does not know them, so they are WORDs, encoded by goasm_c906.th_word of firmware/cpu/go-crypto-c906).
import pathlib, sys
fork = pathlib.Path(__file__).resolve().parent
sys.path.insert(0, str(fork.parents[2] / 'firmware/cpu/go-crypto-c906'))
import goasm_c906 as g

X = lambda r: 'X%d' % g.num(r)
crc, p, n = 'a0', 'a1', 'a2'
T = ['a3', 'a4', 'a5', 'a6', 'a7', 's2', 's3', 's4']        # tables 0..7
v = 't0'
tmp = ['t1', 't2', 't3', 't4', 't5', 's5', 's6', 's7']       # one per byte of the word
o = ['''// Code generated by NanoKVM (gen_crc32c.py). DO NOT EDIT.

//go:build riscv64

#include "textflag.h"

// func crc32cWords(crc uint32, p *byte, words int, tables *[8][256]uint32) uint32
//
// CRC32c over words*8 bytes at p, slicing by 8: the state the caller keeps is
// the inverted checksum. For the T-Head C906: th.extu cuts a byte out of the
// word, th.lrwu loads the table entry by its index; p may be misaligned.
TEXT ·crc32cWords(SB), NOSPLIT|NOFRAME, $0-36''']
o.append(f'\tMOVWU\tcrc+0(FP), {X(crc)}')
o.append(f'\tMOV\tp+8(FP), {X(p)}')
o.append(f'\tMOV\twords+16(FP), {X(n)}')
o.append(f'\tMOV\ttables+24(FP), {X(T[0])}')
for k in range(1, 8):
    o.append(f'\tADD\t$1024, {X(T[k - 1])}, {X(T[k])}')
o.append('loop:')
o.append(f'\tMOV\t({X(p)}), {X(v)}')
o.append(f'\tXOR\t{X(crc)}, {X(v)}, {X(v)}')
def word(op, *a):
    o.append('\tWORD\t$0x%08x\t// %s %s' % (g.th_word(op, list(map(str, a))), op, ', '.join(map(str, a))))
for b in range(8):                       # byte b of the word goes through table 7-b
    word('th.extu', tmp[b], v, 8 * b + 7, 8 * b)
    word('th.lrwu', tmp[b], T[7 - b], tmp[b], 2)
o.append(f'\tADD\t$8, {X(p)}, {X(p)}')
o.append(f'\tADD\t$-1, {X(n)}, {X(n)}')
# a tree, not a chain: the next word waits for crc only
o.append(f'\tXOR\t{X(tmp[0])}, {X(tmp[1])}, {X(tmp[0])}')
o.append(f'\tXOR\t{X(tmp[2])}, {X(tmp[3])}, {X(tmp[2])}')
o.append(f'\tXOR\t{X(tmp[4])}, {X(tmp[5])}, {X(tmp[4])}')
o.append(f'\tXOR\t{X(tmp[6])}, {X(tmp[7])}, {X(tmp[6])}')
o.append(f'\tXOR\t{X(tmp[0])}, {X(tmp[2])}, {X(tmp[0])}')
o.append(f'\tXOR\t{X(tmp[4])}, {X(tmp[6])}, {X(tmp[4])}')
o.append(f'\tXOR\t{X(tmp[0])}, {X(tmp[4])}, {X(crc)}')
o.append(f'\tBNEZ\t{X(n)}, loop')
o.append(f'\tMOVW\t{X(crc)}, ret+32(FP)')
o.append('\tRET')
(fork / 'crc32c_riscv64.s').write_text('\n'.join(o) + '\n')
print('written', fork / 'crc32c_riscv64.s')
